/* KnowNext frontend prototype — vanilla JS only. */
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
let state = loadState();
let currentUser = getSession();
let currentView = '';

function refreshDemoProgress(force=false){
  let saved=null; try{saved=JSON.parse(localStorage.getItem('knownext_demo_progress'));}catch(e){}
  if(!saved || force){
    const random=(min,max)=>Math.floor(Math.random()*(max-min+1))+min;
    saved={topics:{},courses:{}};
    STUDENT_TOPICS.forEach(t=>saved.topics[t.id]=random(54,96));
    COURSES.forEach(c=>saved.courses[c.id]=random(42,96));
    localStorage.setItem('knownext_demo_progress',JSON.stringify(saved));
  }
  STUDENT_TOPICS.forEach(t=>{if(saved.topics?.[t.id]!=null)t.score=saved.topics[t.id];t.recommendation=t.score<70?`Review ${t.name.toLowerCase()}`:t.score<85?`Practice ${t.name.toLowerCase()}`:'Move to the next lesson';});
  COURSES.forEach(c=>{if(saved.courses?.[c.id]!=null)c.progress=saved.courses[c.id];});
}
refreshDemoProgress();

function loadState(){ try { return {...defaultState(), ...(JSON.parse(localStorage.getItem('knownext_state'))||{})}; } catch(e){ return defaultState(); } }
function saveState(){ localStorage.setItem('knownext_state', JSON.stringify(state)); }
function getSession(){ try{return JSON.parse(localStorage.getItem('knownext_session'));}catch(e){return null;} }
function setSession(user){ localStorage.setItem('knownext_session', JSON.stringify({username:user.username,role:user.role})); currentUser={username:user.username,role:user.role}; }
function logout(){ localStorage.removeItem('learnpath_session'); currentUser=null; renderLogin(); }
function user(){ return DEMO_USERS[currentUser?.username]; }
function esc(v){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function calculateMastery(score){return Math.max(0,Math.min(100,score));}
function getStatus(score){ return score<70?'Needs Attention':score<85?'Practice Recommended':'Mastered'; }
function getPriority(score){ return score<70?'HIGH':score<85?'MEDIUM':'LOW'; }
function generateRecommendation(topic){
  if(topic.score<70) return `Review ${topic.name==='Trigonometric Identities'?'Function Transformations':topic.name}`;
  if(topic.score<85) return `Practice ${topic.name.toLowerCase()} exercises`;
  return 'Move to the next topic';
}
function toast(msg){ const el=$('#toast'); el.textContent=msg; el.classList.add('show'); clearTimeout(window._toast); window._toast=setTimeout(()=>el.classList.remove('show'),2400); }
function showModal(title,body,actions=''){ $('#modal-root').innerHTML=`<div class="modal-backdrop" data-close><div class="modal" role="dialog"><button class="modal-x" data-close>×</button><h2>${title}</h2><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</div></div>`; }
function closeModal(){ $('#modal-root').innerHTML=''; }
function navigateTo(view){ if(!currentUser)return renderLogin(); currentView=view; renderApp(); window.scrollTo({top:0,behavior:'smooth'}); }
